import{_ as t,o as s,c as a,ah as o}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Relevés et attestations","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/secretariat/releves-attestations.md","filePath":"src/guide/secretariat/releves-attestations.md"}'),r={name:"guide/secretariat/releves-attestations.md"};function n(i,e,u,l,p,d){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="releves-et-attestations" tabindex="-1">Relevés et attestations <a class="header-anchor" href="#releves-et-attestations" aria-label="Permalink to &quot;Relevés et attestations&quot;">​</a></h1><p>Dans un établissement d&#39;enseignement supérieur, la scolarité imprime les documents que les jurys ont publiés : les <strong>relevés de notes</strong>, session par session, et les <strong>attestations de réussite</strong> au diplôme. Ouvrez <strong>Supérieur → Relevés et attestations</strong>. L&#39;administrateur y a aussi accès.</p><p>Seuls les résultats publiés figurent ici : une délibération en cours, ou rouverte, n&#39;imprime rien tant que le jury ne l&#39;a pas close.</p><h2 id="pour-un-etudiant-au-guichet" tabindex="-1">Pour un étudiant, au guichet <a class="header-anchor" href="#pour-un-etudiant-au-guichet" aria-label="Permalink to &quot;Pour un étudiant, au guichet&quot;">​</a></h2><p>Tapez son <strong>nom</strong>, ou son <strong>matricule</strong> si l&#39;établissement l&#39;utilise, puis <strong>Rechercher</strong>. Pour chaque étudiant trouvé, la page liste :</p><ul><li>son attestation de réussite, s&#39;il a terminé sa filière ;</li><li>ses relevés, du plus récent au plus ancien : promotion, année et session (normale ou rattrapage).</li></ul><p><strong>Relevé de notes</strong> ou <strong>Attestation</strong> télécharge le document en PDF.</p><h2 id="pour-toute-une-promotion" tabindex="-1">Pour toute une promotion <a class="header-anchor" href="#pour-toute-une-promotion" aria-label="Permalink to &quot;Pour toute une promotion&quot;">​</a></h2><p>Sous <strong>Par promotion</strong>, choisissez l&#39;<strong>année</strong>. Chaque promotion dont une session a été publiée propose :</p><ul><li><strong>Relevés — Session normale</strong> et <strong>Relevés — Rattrapage</strong> : les relevés de tous ses étudiants, une page chacun ;</li><li><strong>Attestations</strong> : les attestations déjà délivrées à ses diplômés.</li></ul><p>La scolarité imprime les attestations mais ne les délivre pas : c&#39;est l&#39;administrateur ou le responsable de la filière qui le fait, depuis la page <strong>Diplômés</strong> de la promotion.</p>',11)])])}const m=t(r,[["render",n]]);export{g as __pageData,m as default};
